import openai
import json
import random
from typing import List, Dict

openai.api_key = "your-api-key"

def gpt_judge_compare(prompt: str, response_a: str, response_b: str,
                      model="gpt-4", temperature=0.0) -> Dict:
    """
    使用GPT模型比较两个回复，返回评判结果。
    输出格式: {'winner': 'A'/'B'/'tie', 'reason': '...'}
    """
    # 随机交换顺序以避免位置偏差
    if random.random() < 0.5:
        first, second = "A", "B"
        resp1, resp2 = response_a, response_b
    else:
        first, second = "B", "A"
        resp1, resp2 = response_b, response_a

    judge_prompt = f"""请作为一个公正的评判者，比较以下两个AI助手对用户问题的回复。
用户问题: {prompt}

助手{first}的回复: {resp1}

助手{second}的回复: {resp2}

请从准确性、有用性、流畅度和完整性等方面综合评判。
只输出JSON格式: {{"winner": "{first}"或"{second}"或"tie", "reason": "简要理由"}}
"""
    response = openai.ChatCompletion.create(
        model=model,
        messages=[{"role": "user", "content": judge_prompt}],
        temperature=temperature,
        max_tokens=256
    )
    content = response.choices[0].message.content.strip()
    try:
        result = json.loads(content)
        # 如果因为顺序交换，需要将winner映射回原始的A/B
        if result['winner'] == first:
            result['winner'] = 'A'
        elif result['winner'] == second:
            result['winner'] = 'B'
    except json.JSONDecodeError:
        result = {'winner': 'error', 'reason': content}
    return result


def batch_compare(prompts: List[str], responses_a: List[str], responses_b: List[str]) -> Dict:
    """批量比较，统计胜率"""
    stats = {'A_wins': 0, 'B_wins': 0, 'ties': 0}
    for p, ra, rb in zip(prompts, responses_a, responses_b):
        judge = gpt_judge_compare(p, ra, rb)
        if judge['winner'] == 'A':
            stats['A_wins'] += 1
        elif judge['winner'] == 'B':
            stats['B_wins'] += 1
        else:
            stats['ties'] += 1
    return stats
