class DialogueManager:
    def __init__(self, system_prompt=None):
        self.system_prompt = system_prompt
        self.turns = []

    def add_user(self, content):
        self.turns.append(('user', content))

    def add_assistant(self, content):
        self.turns.append(('assistant', content))

    def format_chatml(self) -> str:
        result = ""
        if self.system_prompt:
            result += f"<|im_start|>system\n{self.system_prompt}<|im_end|>\n"
        for role, content in self.turns:
            result += f"<|im_start|>{role}\n{content}<|im_end|>\n"
        return result

    def extract_training_sample(self) -> dict:
        # 返回最后一个 assistant 回复作为目标，之前的内容作为上下文
        # 实际中更复杂，这里简化
        return self.format_chatml()
