import openai
import json

def evolve_instruction(seed_instruction: str, evolution_type: str = "depth") -> str:
    """
    evolution_type: 'depth' 增加复杂度/约束, 'breadth' 主题迁移/改写
    """
    if evolution_type == "depth":
        prompt = f"""请将以下指令改写得更加复杂和具有挑战性，增加更多限制条件或需要多步推理。
原指令: {seed_instruction}
输出只包含改写后的指令，不需要任何额外文本。"""
    else:
        prompt = f"""请将以下指令的主题或领域进行迁移，保持任务结构不变，但用完全不同的内容替换。
原指令: {seed_instruction}
输出只包含新指令。"""

    response = openai.ChatCompletion.create(
        model="gpt-4",
        messages=[{"role": "user", "content": prompt}],
        temperature=0.7,
        max_tokens=200
    )
    return response.choices[0].message.content.strip()
